        match self {
            Self::Default => "default",
            Self::Private => "private",
        }
    }

    pub fn from_id(value: &str) -> Option<Self> {
        match value.trim().to_ascii_lowercase().as_str() {
            "default" => Some(Self::Default),
            "private" => Some(Self::Private),
            _ => None,
        }
    }
}

